{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Artemisinin and its derivatives are reported to have low oral bioavailability in humans; as a lipophilic sesquiterpene lactone natural product, this supports low F for the similarly lactone-rich, poorly permeable query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Limonin, a highly oxygenated dilactone natural product, shows poor oral bioavailability in humans; its multiple lactone and polar oxygen features resemble the query's dense lactone cage, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Fluticasone has negligible (<1%) oral bioavailability via gastrointestinal absorption, demonstrating that a rigid fused-ring molecule can still have very low oral F despite lipophilic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Amphotericin B has negligible oral bioavailability due to poor membrane permeability and solubility, supporting low F for a highly polar, high-TPSA natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Dexamethasone has high absolute oral bioavailability (81.4 ± 15.8%) in humans, showing that some fused-ring corticosteroids are well absorbed; this is weak contradictory evidence because the query has much higher polarity and lactone content.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Clarithromycin has about 55% oral bioavailability in humans, indicating that even large macrolide natural products can exceed 20% F; weak contradictory evidence due to low structural similarity.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Rosaramicin has an absolute bioavailability of 32 ± 9% in normal volunteers, above the 20% threshold; weak contradictory evidence because the query is much more polar and rigid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a rigid, highly oxygenated polycyclic lactone with low predicted permeability. The most relevant experimental analogues—artemisinin, limonin, amphotericin B, and fluticasone—support low oral bioavailability. High-F steroids and macrolides are too dissimilar to override the low-F pattern, so the prediction is low for the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule itself.",
    "Morgan similarities to all evidence molecules are low (<0.2), limiting transferability.",
    "Threshold-specific absolute F values are lacking for the closest structural analogues.",
    "Potential roles of active transport, efflux, or first-pass metabolism are not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

